-- ============================================================
-- Law library (docs/property_agent_plans/, Phase 3): the text of the laws the Property Law Agent
-- may look up and cite. Filled by docs/pandaslp-law-library-seed.sql (generated by the legal
-- team's scripts/law-library/build.mjs), whose columns this matches exactly.
--
--   law_documents  one row per law: where it applies, whether its text is in (status
--                  'ingested') or not found yet ('not_sourced', with a note saying why).
--   law_sections   the text, one row per section (a long section is split into chunks),
--                  with a keyword index (tsv) and a 384-number embedding for meaning search.
--
-- Search combines keywords (search_law_sections) and meaning (match_law_sections, over the
-- seed's gte-small embeddings); the app merges the two rankings. The query is embedded by the
-- app with the same model (lib/property/embeddings.ts).
--
-- Server-only: RLS on with no policies, no privileges for the browser's roles.
-- Also: the 'law_lookup' event kind on property_matter_events, so a section looked up in one
-- turn can still be cited in a later turn of the same matter.
--
-- Needs the pgvector extension (Supabase: Database → Extensions → vector, or the line below).
-- RUN ORDER: after add-property-matters.sql, then load the seed. Safe to re-run.
-- ============================================================

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

CREATE TABLE IF NOT EXISTS public.law_documents (
  id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          TEXT        NOT NULL UNIQUE,
  title         TEXT        NOT NULL,
  citation      TEXT,
  -- 'federal', 'fct' or 'state'.
  jurisdiction  TEXT        NOT NULL,
  -- 'All states', or the one state it belongs to ('Lagos', 'FCT', 'Delta', ...).
  state         TEXT        NOT NULL,
  -- Plain words on where it applies, e.g. the Lagos Tenancy Law's excluded areas.
  applies_in    TEXT,
  year          INTEGER,
  topics        TEXT[]      NOT NULL DEFAULT '{}',
  -- 'ingested' = text loaded; 'not_sourced' = official text not found yet (see notes).
  status        TEXT        NOT NULL,
  source_name   TEXT,
  source_url    TEXT,
  retrieved_on  DATE,
  notes         TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.law_sections (
  id           BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_id  UUID        NOT NULL REFERENCES public.law_documents(id) ON DELETE CASCADE,
  -- The section number as the law prints it: '22', '13', '4A'.
  section      TEXT        NOT NULL,
  -- 1 for the first part of a section; a long section continues in chunk 2, 3...
  chunk        INTEGER     NOT NULL DEFAULT 1,
  heading      TEXT,
  part         TEXT,
  content      TEXT        NOT NULL,
  embedding    extensions.vector(384),
  tsv          TSVECTOR    GENERATED ALWAYS AS (
                 setweight(to_tsvector('english', coalesce(heading, '')), 'A') ||
                 setweight(to_tsvector('english', content), 'B')
               ) STORED,
  UNIQUE (document_id, section, chunk)
);

CREATE INDEX IF NOT EXISTS law_sections_tsv_idx ON public.law_sections USING GIN (tsv);
CREATE INDEX IF NOT EXISTS law_sections_document_idx ON public.law_sections (document_id, section, chunk);
CREATE INDEX IF NOT EXISTS law_documents_state_idx ON public.law_documents (state);

-- Keyword search over the laws that apply in a state (plus every 'All states' law).
-- p_query is a to_tsquery OR-query built by the app from the client's words
-- ("landlord | increase | rent | notice", lib/property/lawLookup.ts orQuery): a section
-- matching more of the words ranks higher, and one missing word doesn't drop it.
CREATE OR REPLACE FUNCTION public.search_law_sections(p_query TEXT, p_state TEXT, p_limit INTEGER DEFAULT 5)
RETURNS TABLE (slug TEXT, title TEXT, section TEXT, chunk INTEGER, heading TEXT, content TEXT, rank REAL)
LANGUAGE sql STABLE
AS $$
  SELECT d.slug, d.title, s.section, s.chunk, s.heading, s.content,
         ts_rank_cd(s.tsv, q) AS rank
    FROM public.law_sections s
    JOIN public.law_documents d ON d.id = s.document_id,
         to_tsquery('english', p_query) q
   WHERE s.tsv @@ q
     AND d.status = 'ingested'
     AND (d.state = 'All states' OR d.state = p_state)
   ORDER BY rank DESC, d.slug, s.section, s.chunk
   LIMIT LEAST(GREATEST(p_limit, 1), 10);
$$;

-- Meaning search: the sections whose embedding is closest to the question's (cosine), over the
-- same laws as search_law_sections. The question is embedded by the app with the same model as
-- the seed (gte-small, lib/property/embeddings.ts). Results from both searches are merged in
-- the app (lib/property/lawLookup.ts fuseRankings).
CREATE INDEX IF NOT EXISTS law_sections_embedding_idx
  ON public.law_sections USING hnsw (embedding extensions.vector_cosine_ops);

CREATE OR REPLACE FUNCTION public.match_law_sections(p_embedding extensions.vector(384), p_state TEXT, p_limit INTEGER DEFAULT 5)
RETURNS TABLE (slug TEXT, title TEXT, section TEXT, chunk INTEGER, heading TEXT, content TEXT, similarity REAL)
LANGUAGE sql STABLE
SET search_path = public, extensions
AS $$
  SELECT d.slug, d.title, s.section, s.chunk, s.heading, s.content,
         (1 - (s.embedding <=> p_embedding))::REAL AS similarity
    FROM public.law_sections s
    JOIN public.law_documents d ON d.id = s.document_id
   WHERE s.embedding IS NOT NULL
     AND d.status = 'ingested'
     AND (d.state = 'All states' OR d.state = p_state)
   ORDER BY s.embedding <=> p_embedding
   LIMIT LEAST(GREATEST(p_limit, 1), 20);
$$;

ALTER TABLE public.law_documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.law_sections  ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.law_documents, public.law_sections FROM anon, authenticated;
REVOKE ALL ON FUNCTION public.search_law_sections(TEXT, TEXT, INTEGER) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.match_law_sections(extensions.vector, TEXT, INTEGER) FROM PUBLIC, anon, authenticated;

-- law_lookup: a section looked up by the agent, so it may be cited in a later turn of the same matter.
-- web_search: a search of the trusted law websites (query and the URLs found), for the lawyer to see.
ALTER TABLE public.property_matter_events DROP CONSTRAINT IF EXISTS property_matter_events_kind_check;
ALTER TABLE public.property_matter_events ADD CONSTRAINT property_matter_events_kind_check
  CHECK (kind IN ('routed', 'handoff', 'escalated', 'fee_accepted', 'document_emitted', 'law_lookup', 'web_search'));
